CREATE TABLE IF NOT EXISTS `about_pages` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `content` LONGTEXT NOT NULL,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `page_contents` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `content` LONGTEXT NOT NULL,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `page_contents` (`id`, `slug`, `content`, `created_at`, `updated_at`) VALUES (1, CONVERT(X'686F6D65' USING utf8mb4), CONVERT(X'' USING utf8mb4), CONVERT(X'323032362D31312D32302031333A30353A3036' USING utf8mb4), CONVERT(X'323032362D31312D32302031333A31323A3434' USING utf8mb4));
