CREATE TABLE IF NOT EXISTS `attendances` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
`user_id` BIGINT UNSIGNED NOT NULL,
`activity_id` BIGINT UNSIGNED NOT NULL,
  `status` VARCHAR(255) NOT NULL DEFAULT 'hadir',
  `note` LONGTEXT,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_attendances_activity_id` FOREIGN KEY (`activity_id`) REFERENCES `activities` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_attendances_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `user_material_progress` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
`user_id` BIGINT UNSIGNED NOT NULL,
`material_id` BIGINT UNSIGNED NOT NULL,
  `status` VARCHAR(255) NOT NULL DEFAULT 'belum_dibaca',
  `completed_at` DATETIME,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_user_material_progress_material_id` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_user_material_progress_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `achievements` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `description` LONGTEXT,
  `icon` VARCHAR(255) NOT NULL DEFAULT '🏆',
  `type` VARCHAR(255) NOT NULL DEFAULT 'khusus',
  `requirement_value` BIGINT NOT NULL DEFAULT '0',
  `reward_points` BIGINT NOT NULL DEFAULT '0',
  `is_active` TINYINT(1) NOT NULL DEFAULT '1',
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `user_achievements` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
`user_id` BIGINT UNSIGNED NOT NULL,
`achievement_id` BIGINT UNSIGNED NOT NULL,
  `earned_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_user_achievements_achievement_id` FOREIGN KEY (`achievement_id`) REFERENCES `achievements` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_user_achievements_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Indexes
CREATE UNIQUE INDEX `users_email_unique` ON `users` (`email`);
CREATE INDEX `sessions_last_activity_index` ON `sessions` (`last_activity`);
CREATE INDEX `sessions_user_id_index` ON `sessions` (`user_id`);
CREATE INDEX `cache_expiration_index` ON `cache` (`expiration`);
CREATE INDEX `cache_locks_expiration_index` ON `cache_locks` (`expiration`);
CREATE INDEX `jobs_queue_index` ON `jobs` (`queue`);
CREATE UNIQUE INDEX `failed_jobs_uuid_unique` ON `failed_jobs` (`uuid`);
CREATE INDEX `failed_jobs_connection_queue_failed_at_index` ON `failed_jobs` (`connection`, `queue`, `failed_at`);
CREATE UNIQUE INDEX `news_slug_unique` ON `news` (`slug`);
CREATE UNIQUE INDEX `page_contents_slug_unique` ON `page_contents` (`slug`);
CREATE UNIQUE INDEX `attendances_user_id_activity_id_unique` ON `attendances` (`user_id`, `activity_id`);
CREATE UNIQUE INDEX `user_material_progress_user_id_material_id_unique` ON `user_material_progress` (`user_id`, `material_id`);
CREATE UNIQUE INDEX `user_achievements_user_id_achievement_id_unique` ON `user_achievements` (`user_id`, `achievement_id`);

COMMIT;
SET FOREIGN_KEY_CHECKS=1;
